import sys,json,time,pathlib
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot,EpisodeOver
import numpy as np
from PIL import Image
from scipy.spatial import cKDTree
from scipy.spatial.transform import Rotation as Rot
from scipy.optimize import least_squares
OUT=pathlib.Path('/app/output'); OUT.mkdir(exist_ok=True)
r=Robot(); spec=r.spec(); cams=list(spec['cameras']); counter=0

def cloud(obs,cam,mask=None):
 d=obs.depth[cam].astype(float); im=obs.last[cam]
 K=np.array(obs.meta['cameras'][cam]['intrinsic_cv']); T=np.array(obs.meta['cameras'][cam]['cam2world_gl'])
 v,u=np.indices(d.shape); p=np.stack([(u-K[0,2])*d/K[0,0],-(v-K[1,2])*d/K[1,1],-d],-1)
 p=p@T[:3,:3].T+T[:3,3]
 if mask is None:return p,im
 return p[mask],im[mask]

def save(obs,name):
 obs.save(str(OUT/name))
 ims=[]
 for cam in cams:
  if cam in obs.last: ims.append(Image.fromarray(obs.last[cam]).resize((640,480)))
 if ims:
  canvas=Image.new('RGB',(1280,960))
  for i,im in enumerate(ims):canvas.paste(im,((i%2)*640,(i//2)*480))
  canvas.save(OUT/'view.png')

def info(obs):
 print('time',obs.meta.get('time_left_s'),'steps',obs.meta['control_steps'],'task',obs.meta['task'],flush=True)
 print('q',np.round(obs.meta['proprio']['now'][:29],4),flush=True)

def observe():
 global obs
 obs=r.get_obs(cameras=cams,include_depth=True);save(obs,'latest');return obs

def move(q,seconds=1,hold=.3,note=''):
 global obs,counter
 q=np.asarray(q); counter+=1
 a=np.repeat(q[None,:],2,axis=0)
 # one row reaches target over seconds, next maintains it for hold
 data={'q':q.tolist(),'seconds':seconds,'hold':hold,'note':note}
 with open(OUT/'actions.jsonl','a') as f:f.write(json.dumps(data)+'\n')
 obs=r.submit('joint_position',q,dt=round(seconds*60)/60,cameras=cams,include_depth=True,video='frames',video_fps=5,note=note)
 if hold and not obs.done:obs=r.get_obs(cameras=cams,include_depth=True,seconds=hold)
 save(obs,f'run{counter:03d}');info(obs);return obs

def target():return np.array(obs.meta['proprio']['now'][58:87])
def joints():return np.array(obs.meta['proprio']['now'][:29])

def getpoints(obs,lo=None,hi=None,white=False,green=False):
 points=[]
 for cam in cams:
  p,im=cloud(obs,cam);mask=np.isfinite(p).all(-1)
  if lo is not None:mask &= (p>lo).all(-1)
  if hi is not None:mask &= (p<hi).all(-1)
  if white:mask &= (im.min(-1)>130)&((im.max(-1).astype(float)-im.min(-1))<50)
  if green:mask &= (im[:,:,1]>im[:,:,0]*1.4)&(im[:,:,1]>im[:,:,2]*1.4)&(im[:,:,1]>80)
  else:mask &= ~((im[:,:,1]>im[:,:,0]*1.4)&(im[:,:,1]>im[:,:,2]*1.4)&(im[:,:,1]>80))
  points.append(p[mask])
 return np.concatenate(points)

def rigid(A,B):
 a=A.mean(0);b=B.mean(0);U,s,V=np.linalg.svd((A-a).T@(B-b));R=V.T@U.T
 if np.linalg.det(R)<0:V[-1]*=-1;R=V.T@U.T
 return R,b-R@a

def icp(A,B,init=None,iterations=50,th=.025):
 tree=cKDTree(B);R=np.eye(3);t=np.zeros(3)
 if init is not None:R,t=init
 for i in range(iterations):
  C=A@R.T+t;dd,idx=tree.query(C);good=dd<th
  dR,dt=rigid(C[good],B[idx[good]]);R=dR@R;t=dR@t+dt
  if np.linalg.norm(dt)<1e-6 and np.linalg.norm(Rot.from_matrix(dR).as_rotvec())<1e-5:break
 return R,t,np.sqrt(np.mean(dd[good]**2)),good.sum()

obs=observe();info(obs)
